import AppKit
import SwiftUI

// MARK: - The lettering

/// One greeting of the launch screen: Pacifico's outline of it, and the pen's way along its letters
/// with the pen's pace. The greetings themselves (`WelcomeLettering.all`, WelcomeLettering.swift)
/// are generated by design/tools/welcome_lettering.py from the font (design/fonts/Pacifico, SIL Open
/// Font License 1.1) — the same data as the approved prototype (design/prototypes/welcome.html).
struct WelcomeLettering {
    /// One stroke of the pen: on the paper from `start` to `end`, seconds of the writing.
    struct Stroke {
        /// A dot or an accent, written after its word.
        let mark: Bool
        let start: Double
        let end: Double
        /// Cubic Béziers, each [start, control, control, end], in x-heights.
        let segments: [[CGPoint]]
        /// Where the pen is every 1/120 s from `start`: a segment's index plus how far along it.
        let pen: [Double]

        /// `path`: "M x y C x1 y1 x2 y2 x y …"; `pen`: the positions, space-separated.
        init(mark: Bool, start: Double, end: Double, path: String, pen: String) {
            self.mark = mark
            self.start = start
            self.end = end
            let numbers = path.split(separator: " ").compactMap { Double($0) }
            var segments: [[CGPoint]] = []
            if numbers.count >= 2 {
                var last = CGPoint(x: numbers[0], y: numbers[1])
                var index = 2
                while index + 6 <= numbers.count {
                    let next = CGPoint(x: numbers[index + 4], y: numbers[index + 5])
                    segments.append([last, CGPoint(x: numbers[index], y: numbers[index + 1]),
                                     CGPoint(x: numbers[index + 2], y: numbers[index + 3]), next])
                    last = next
                    index += 6
                }
            }
            self.segments = segments
            self.pen = pen.split(separator: " ").compactMap { Double($0) }
        }

        /// The pen's positions are this many a second.
        static let rate: Double = 120

        /// Where the pen is at `time` (seconds of the writing): 0 before the stroke, the number of
        /// its segments once it is written.
        func position(at time: Double) -> Double {
            let written = Double(segments.count)
            guard time > start else { return 0 }
            guard time < end, pen.count > 1 else { return written }
            let place = (time - start) * Self.rate
            let index = Int(place)
            guard index + 1 < pen.count else { return pen.last ?? written }
            return pen[index] + (pen[index + 1] - pen[index]) * (place - Double(index))
        }

        /// The stroke between pen positions `from` and `to`, each point put where `place` says.
        func path(from: Double, to: Double, place: (CGPoint) -> CGPoint) -> Path {
            var path = Path()
            let count = Double(segments.count)
            let from = max(0, min(count, from)), to = max(0, min(count, to))
            guard to - from > 1e-4 else { return path }
            let first = Int(from.rounded(.down))
            let last = min(segments.count - 1, Int((to - 1e-9).rounded(.down)))
            guard first <= last else { return path }
            for index in first...last {
                var segment = segments[index]
                let end = index == last ? to - Double(index) : 1
                let begin = index == first ? from - Double(index) : 0
                if end < 1 { segment = Self.split(segment, at: CGFloat(end)).head }
                if begin > 0 { segment = Self.split(segment, at: CGFloat(begin / end)).tail }
                let points = segment.map(place)
                if index == first { path.move(to: points[0]) }
                path.addCurve(to: points[3], control1: points[1], control2: points[2])
            }
            return path
        }

        /// A cubic cut in two at `t` (de Casteljau).
        private static func split(_ s: [CGPoint], at t: CGFloat) -> (head: [CGPoint], tail: [CGPoint]) {
            func mix(_ a: CGPoint, _ b: CGPoint) -> CGPoint { CGPoint(x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t) }
            let a = mix(s[0], s[1]), b = mix(s[1], s[2]), c = mix(s[2], s[3])
            let d = mix(a, b), e = mix(b, c), f = mix(d, e)
            return ([s[0], a, d, f], [f, e, c, s[3]])
        }
    }

    /// The greeting's language ("ru", "en", "de", …).
    let code: String
    /// The greeting as text: what VoiceOver reads.
    let text: String
    /// How long the writing takes, seconds.
    let duration: Double
    let lineCount: Int
    /// The reveal's width — the pen's stroke, a little wider than the font's widest — x-heights.
    let reveal: Double
    /// What the greeting covers, in x-heights.
    let bounds: CGRect
    /// Pacifico's outline of the greeting: "M x y", "L x y", "Q x1 y1 x y", "C …", "Z", in x-heights.
    let outline: String
    let strokes: [Stroke]

    /// The font's widest stroke, x-heights (the reveal is 1.22 of it: design/tools/welcome_lettering.py).
    var stroke: Double { reveal / 1.22 }

    /// When the last stroke ends (the dots after the words included), seconds of the writing.
    var lastEnd: Double { strokes.map(\.end).max() ?? duration }

    /// The outline, each point put where `place` says.
    func outlinePath(place: (CGPoint) -> CGPoint) -> Path {
        var path = Path()
        let tokens = outline.split(separator: " ")
        var index = 0
        while index < tokens.count {
            let command = tokens[index]
            index += 1
            var numbers: [CGFloat] = []
            while index < tokens.count, let value = Double(tokens[index]) {
                numbers.append(CGFloat(value))
                index += 1
            }
            var points: [CGPoint] = []
            var k = 0
            while k + 1 < numbers.count {
                points.append(place(CGPoint(x: numbers[k], y: numbers[k + 1])))
                k += 2
            }
            switch command {
            case "M" where points.count >= 1: path.move(to: points[0])
            case "L" where points.count >= 1: path.addLine(to: points[0])
            case "Q" where points.count >= 2: path.addQuadCurve(to: points[1], control: points[0])
            case "C" where points.count >= 3: path.addCurve(to: points[2], control1: points[0], control2: points[1])
            case "Z": path.closeSubpath()
            default: break
            }
        }
        return path
    }

    /// Everything the pen has gone along by `time` (seconds of the writing).
    func written(at time: Double, place: (CGPoint) -> CGPoint) -> Path {
        var path = Path()
        for stroke in strokes {
            path.addPath(stroke.path(from: 0, to: stroke.position(at: time), place: place))
        }
        return path
    }

    /// The last `span` seconds of the pen's way at `time`; nil when there is none.
    func trail(at time: Double, span: Double, place: (CGPoint) -> CGPoint) -> Path? {
        var path = Path()
        for stroke in strokes where time > stroke.start && time < stroke.end + span {
            path.addPath(stroke.path(from: stroke.position(at: time - span), to: stroke.position(at: time), place: place))
        }
        return path.isEmpty ? nil : path
    }

    /// The greeting for VoiceOver, said in its own language.
    var spoken: AttributedString {
        var spoken = AttributedString(text)
        spoken.languageIdentifier = code
        return spoken
    }
}

// MARK: - Timing and layout

/// The launch screen's times, in seconds from its start: the approved prototype's `T`.
struct WelcomeTiming {
    /// The horizon fades and rises in.
    static let arcIn = 0.5
    /// The pen starts.
    static let penStart = 0.3
    /// Once written, a light runs along the greeting in the order it was written.
    static let settle = 0.75
    /// "LUMEN" after the writing, and how long it fades in.
    static let wordmarkDelay = 0.15
    static let wordmarkIn = 0.6
    /// The first launch's button after the writing, and how long it fades in.
    static let buttonDelay = 0.35
    static let buttonIn = 0.5
    /// From the end of the writing to the opening, on a later launch.
    static let hold = 0.9
    /// The opening: the screen eases up 30 pt and fades, the window's content scales in.
    static let opening = 0.6
    /// Reduce Motion: the greeting fades in whole, stays, and the screen cross-fades.
    static let reducedIn = 0.4
    static let reducedHold = 1.2
    static let reducedOpening = 0.4
    /// The pen's fresh stroke (brighter), and the settle's light: how much of the pen's way each covers.
    static let trail = 0.14
    static let glint = 0.32

    let duration: Double
    let reduced: Bool

    /// The writing is done.
    var writtenAt: Double { Self.penStart + duration }
    /// Nothing moves any more (until the opening).
    var settledAt: Double {
        if reduced { return Self.reducedIn }
        return writtenAt + max(Self.settle * 1.2, Self.wordmarkDelay + Self.wordmarkIn, Self.buttonDelay + Self.buttonIn) + 0.05
    }
    /// A later launch opens by itself.
    var openAt: Double { reduced ? Self.reducedIn + Self.reducedHold : writtenAt + Self.hold }
    /// How long the opening takes.
    var opening: Double { reduced ? Self.reducedOpening : Self.opening }
}

/// Where everything stands in a window of `size`: the approved prototype's `layout`.
struct WelcomeLayout {
    let size: CGSize
    let horizon: LumenHorizon.Geometry
    /// The x-height: the mock's 6.8 % of the height; a short greeting larger, up to 9.5 %, so that
    /// it spans about 44 % of the width; never wider than 86 % of the window.
    let xHeight: CGFloat
    /// The last line's baseline: just under the horizon's top, the letters on the light.
    let baseline: CGFloat
    /// The font's widest stroke, and the pen's (the reveal), points.
    let stroke: CGFloat
    let reveal: CGFloat
    /// The top of "LUMEN".
    let wordmarkTop: CGFloat
    /// The glass's own frame: what the greeting covers, with room for its glow.
    let glassRect: CGRect

    init(size: CGSize, greeting: WelcomeLettering) {
        self.size = size
        horizon = LumenHorizon.Geometry(width: size.width, height: size.height)
        let words = max(greeting.bounds.width, 1)
        let xHeight = min(min(max(size.height * 0.068, size.width * 0.44 / words), size.height * 0.095),
                          size.width * 0.86 / words)
        self.xHeight = max(xHeight, 1)
        baseline = horizon.top + 0.62 * self.xHeight
        stroke = CGFloat(greeting.stroke) * self.xHeight
        reveal = CGFloat(greeting.reveal) * self.xHeight
        wordmarkTop = baseline + max(0.95, greeting.bounds.maxY + 0.42) * self.xHeight
        let pad = stroke * 1.6
        glassRect = CGRect(x: size.width / 2 + greeting.bounds.minX * self.xHeight - pad,
                           y: baseline + greeting.bounds.minY * self.xHeight - pad,
                           width: greeting.bounds.width * self.xHeight + 2 * pad,
                           height: greeting.bounds.height * self.xHeight + 2 * pad)
    }

    /// A point of the lettering (x-heights) in the glass's own frame.
    func inGlass(_ point: CGPoint) -> CGPoint {
        CGPoint(x: size.width / 2 + point.x * xHeight - glassRect.minX, y: baseline + point.y * xHeight - glassRect.minY)
    }
}

// MARK: - The screen

/// The launch screen (the owner, 15 November: "at the first launch, and at a launch after a full
/// quit, a greeting like the one a new MacBook writes while you set it up — in different languages,
/// drawn beautifully as with a pen, a couple of seconds, then the app opens smoothly"; the mock: a
/// handwritten greeting in liquid glass over the eclipse's horizon, "L U M E N" under it, a small
/// button; the look and timing the owner approved in design/prototypes/welcome.html).
///
/// The greeting is Pacifico's own outline, revealed by a pen moving along its letters
/// (WelcomeLettering), in clear glass lit by the horizon (WelcomeGlass: Metal, compiled as the app
/// starts; SwiftUI's drawn outline where Metal is missing). The pen's fresh stroke is brighter; once
/// written a light runs along the greeting, "LUMEN" fades in, and then: at the first launch the
/// button (setup comes next); at a later launch a moment's hold and the opening by itself. Any click
/// or key opens at once. The opening is the screen's own — it eases up 30 pt and fades in 0.6 s —
/// while RootView brings the window's content in over it (`opening`), then lets it go (`finished`).
/// Under Reduce Motion (or with the animations off) the greeting fades in whole and the screen
/// cross-fades. VoiceOver reads the greeting as text, in its own language, with an action that goes on.
struct WelcomeSplash: View {
    let greeting: WelcomeLettering
    /// The first launch: the button leads on; otherwise the screen goes on by itself.
    let firstLaunch: Bool
    /// The opening begins: the window's content comes in over the screen. Called once.
    let opening: () -> Void
    /// The opening is over: the screen can go. Called once.
    let finished: () -> Void
    /// The snapshots: the screen at this time (seconds from its start), still.
    var still: Double?
    /// The snapshots: the glass as drawn where Metal is missing.
    var fallbackGlass = false

    @Environment(\.accessibilityReduceMotion) private var systemReduceMotion
    @Environment(\.lumenStillFrame) private var stillFrame
    @Environment(\.displayScale) private var displayScale
    /// When the screen started — once the glass is ready (or not coming): nil until then.
    @State private var start: Date?
    /// The glass is Metal's (decided as the screen starts, kept to its end).
    @State private var metal = false
    @State private var settled = false
    /// When the opening began, seconds from the start.
    @State private var openedAt: Double?
    @State private var cache = WelcomeSplashCache()
    @FocusState private var focused: Bool

    private var reduced: Bool { Motion.isReduced(systemReduceMotion) }
    private var timing: WelcomeTiming { WelcomeTiming(duration: greeting.duration, reduced: reduced) }
    /// A still frame: the snapshots' time, or (any other still picture) the settled screen.
    private var stillTime: Double? { still ?? (stillFrame ? timing.settledAt + 0.5 : nil) }
    /// Nothing moves: a still, before the start, or the first launch waiting for its button.
    private var paused: Bool { stillTime != nil || start == nil || (settled && openedAt == nil) }

    var body: some View {
        GeometryReader { geometry in
            let layout = WelcomeLayout(size: geometry.size, greeting: greeting)
            ZStack {
                TimelineView(.animation(minimumInterval: nil, paused: paused)) { context in
                    scene(at: time(at: context.date), layout: layout)
                }
                // VoiceOver's: the greeting as text, where it is drawn.
                Color.clear
                    .frame(width: layout.glassRect.width, height: layout.glassRect.height)
                    .position(x: layout.glassRect.midX, y: layout.glassRect.midY)
                    .accessibilityElement()
                    .accessibilityLabel(Text(greeting.spoken))
                    .accessibilityAddTraits(.isHeader)
                    .accessibilityHint(L("welcome.hint"))
                    .accessibilityAction(named: L("welcome.skip")) { go() }
            }
        }
        .background(Theme.backdrop)
        .ignoresSafeArea()
        .contentShape(Rectangle())
        .onTapGesture { go() }
        // Any key goes on; the screen holds the keyboard's focus without a ring.
        .focusable()
        .focused($focused)
        .focusEffectDisabled()
        .onKeyPress(phases: .down) { _ in
            go()
            return .handled
        }
        .onAppear { focused = true }
        .task { await run() }
    }

    private func time(at date: Date) -> Double {
        if let stillTime { return stillTime }
        guard let start else { return 0 }
        return date.timeIntervalSince(start)
    }

    /// The screen's own course: it starts once the glass's shader is ready (compiled as the app
    /// started; 0.8 s at most, then the drawn glass), stills once everything has come in, and on a
    /// later launch opens by itself.
    private func run() async {
        guard stillTime == nil else { return }
        let deadline = Date().addingTimeInterval(0.8)
        while WelcomeGlassRenderer.isPreparing, Date() < deadline, !Task.isCancelled {
            try? await Task.sleep(nanoseconds: 16_000_000)
        }
        guard !Task.isCancelled else { return }
        if start == nil {
            metal = !fallbackGlass && WelcomeGlassRenderer.shared != nil
            start = Date()
        }
        let wait = firstLaunch ? timing.settledAt : timing.openAt
        try? await Task.sleep(nanoseconds: UInt64(max(0, wait) * 1_000_000_000))
        guard !Task.isCancelled, openedAt == nil else { return }
        if firstLaunch {
            settled = true
        } else {
            go()
        }
    }

    /// The opening, once: the screen eases up and fades by itself (the timeline) while RootView
    /// brings the window's content in; when it is over the screen and its glass go.
    private func go() {
        guard openedAt == nil, stillTime == nil else { return }
        let now = Date()
        if start == nil {
            metal = !fallbackGlass && WelcomeGlassRenderer.shared != nil
            start = now
        }
        openedAt = now.timeIntervalSince(start ?? now)
        settled = false
        opening()
        let length = timing.opening
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: UInt64(length * 1_000_000_000))
            finished()
            WelcomeGlassRenderer.release()
        }
    }

    // MARK: One frame

    @ViewBuilder
    private func scene(at time: Double, layout: WelcomeLayout) -> some View {
        let open = openedAt.map { progress(time, $0, timing.opening) } ?? 0
        let leave = reduced ? open : easeInOut(open)
        let lift: CGFloat = reduced ? 0 : -30 * CGFloat(leave)
        let splashAlpha = 1 - leave
        let arcIn = reduced ? progress(time, 0, WelcomeTiming.reducedIn) : easeOut(progress(time, 0, WelcomeTiming.arcIn))
        let wordmarkIn = reduced ? progress(time, 0, WelcomeTiming.reducedIn)
            : easeOut(progress(time, timing.writtenAt + WelcomeTiming.wordmarkDelay, WelcomeTiming.wordmarkIn))
        let buttonIn = !firstLaunch ? 0 : reduced ? progress(time, 0, WelcomeTiming.reducedIn)
            : easeOut(progress(time, timing.writtenAt + WelcomeTiming.buttonDelay, WelcomeTiming.buttonIn))
        let horizonImage = cache.horizon(size: layout.size, scale: displayScale)

        ZStack(alignment: .topLeading) {
            if let horizonImage {
                Image(decorative: horizonImage, scale: displayScale)
                    .resizable()
                    .frame(width: layout.size.width, height: layout.size.height)
                    .opacity(arcIn * splashAlpha)
                    .offset(y: CGFloat(reduced ? 0 : (1 - arcIn) * 10) + lift)
                glass(at: time, layout: layout, horizon: horizonImage, alpha: splashAlpha, lift: lift)
                    .frame(width: layout.glassRect.width, height: layout.glassRect.height)
                    .offset(x: layout.glassRect.minX, y: layout.glassRect.minY + lift)
                    .allowsHitTesting(false)
            }
            wordmark(layout)
                .opacity(wordmarkIn * splashAlpha)
                .offset(y: lift)
            if firstLaunch {
                startButton
                    .position(x: layout.size.width / 2, y: layout.size.height - max(64, layout.size.height * 0.11))
                    .offset(y: lift)
                    .opacity(buttonIn * splashAlpha)
                    .allowsHitTesting(buttonIn > 0.5 && openedAt == nil)
                    .accessibilityHidden(buttonIn == 0)
            }
        }
        .frame(width: layout.size.width, height: layout.size.height, alignment: .topLeading)
    }

    /// The greeting in glass at `time`: what the pen has written, its fresh stroke, the settle's light.
    private func glass(at time: Double, layout: WelcomeLayout, horizon: CGImage, alpha: Double, lift: CGFloat) -> AnyView {
        let writing = reduced ? Double.greatestFiniteMagnitude : time - WelcomeTiming.penStart
        let place: (CGPoint) -> CGPoint = { layout.inGlass($0) }
        let outline = cache.outline(greeting, layout: layout)
        let full = writing >= greeting.lastEnd
        let revealed: Path? = full ? nil : greeting.written(at: writing, place: place)
        let trail = reduced ? nil : greeting.trail(at: writing, span: WelcomeTiming.trail, place: place)
        // The settle: one light along the finished greeting, in the order it was written, faster.
        let sweep = reduced ? -1 : (time - timing.writtenAt) / WelcomeTiming.settle
        let glint: Path? = sweep > 0 && sweep < 1.2
            ? greeting.trail(at: easeInOut(min(max(sweep, 0), 1)) * greeting.duration + (sweep > 1 ? (sweep - 1) * greeting.duration : 0),
                             span: WelcomeTiming.glint, place: place)
            : nil
        let greetingIn = reduced ? easeOut(progress(time, 0, WelcomeTiming.reducedIn)) : 1
        let useMetal = stillTime == nil ? metal : !fallbackGlass
        if useMetal, let renderer = stillTime == nil ? WelcomeGlassRenderer.shared : WelcomeGlassRenderer.prepareNow() {
            let frame = WelcomeGlassFrame(outline: outline.cgPath, revealed: revealed?.cgPath, trail: trail?.cgPath,
                                          glint: glint?.cgPath, reveal: layout.reveal, stroke: layout.stroke,
                                          size: layout.glassRect.size,
                                          origin: CGPoint(x: layout.glassRect.minX, y: layout.glassRect.minY + lift),
                                          view: layout.size, scale: displayScale, alpha: greetingIn * alpha, horizon: horizon)
            if stillTime != nil {
                // A still (the snapshots): the glass drawn once, as a picture.
                if let picture = cache.still(frame, renderer: renderer, key: time) {
                    return AnyView(Image(decorative: picture, scale: displayScale).resizable())
                }
            } else {
                return AnyView(WelcomeGlassSurface(frame: frame, renderer: renderer))
            }
        }
        return AnyView(WelcomeFallbackGlass(outline: outline, revealed: revealed, reveal: layout.reveal, stroke: layout.stroke)
            .opacity(greetingIn * alpha))
    }

    /// "L U M E N", small and tracked wide, under the greeting.
    private func wordmark(_ layout: WelcomeLayout) -> some View {
        let size = max(11, 0.24 * layout.xHeight)
        let tracking = 0.62 * size
        return Text(verbatim: "LUMEN")
            .font(.system(size: size, weight: .semibold))
            .tracking(tracking)
            // The tracking stands after the last letter too: the word is centred without it.
            .padding(.leading, tracking)
            .foregroundStyle(Theme.textPrimary.opacity(0.46))
            .fixedSize()
            .position(x: layout.size.width / 2, y: layout.wordmarkTop + size * 0.6)
            .accessibilityHidden(true)
    }

    /// The first launch's "Get started": macOS 26's glass button, before it the mock's dark pill.
    private var startButton: AnyView {
        let button = Button(L("welcome.start")) { go() }
        #if compiler(>=6.2)
        if #available(macOS 26, *), stillTime == nil {
            return AnyView(button.buttonStyle(.glass).controlSize(.large))
        }
        #endif
        return AnyView(button.buttonStyle(WelcomeButtonStyle()))
    }

    private func progress(_ time: Double, _ from: Double, _ length: Double) -> Double {
        max(0, min(1, (time - from) / length))
    }

    private func easeOut(_ x: Double) -> Double { 1 - pow(1 - x, 3) }

    /// The prototype's cubic in-out.
    private func easeInOut(_ x: Double) -> Double { x < 0.5 ? 4 * x * x * x : 1 - pow(-2 * x + 2, 3) / 2 }
}

/// What the launch screen makes once and keeps: the horizon's picture and the greeting's outline
/// for the window's size, and (the snapshots) the still glass.
final class WelcomeSplashCache {
    private var horizonKey: (CGSize, CGFloat)?
    private var horizonPicture: CGImage?
    private var outlineKey: CGSize?
    private var outlinePath = Path()
    private var stillKey: (CGSize, Double)?
    private var stillPicture: CGImage?

    func horizon(size: CGSize, scale: CGFloat) -> CGImage? {
        guard size.width >= 1, size.height >= 1 else { return nil }
        if let key = horizonKey, key.0 == size, key.1 == scale { return horizonPicture }
        horizonKey = (size, scale)
        horizonPicture = LumenHorizon.image(size: size, scale: scale)
        return horizonPicture
    }

    func outline(_ greeting: WelcomeLettering, layout: WelcomeLayout) -> Path {
        if outlineKey != layout.size {
            outlineKey = layout.size
            outlinePath = greeting.outlinePath(place: { layout.inGlass($0) })
        }
        return outlinePath
    }

    func still(_ frame: WelcomeGlassFrame, renderer: WelcomeGlassRenderer, key time: Double) -> CGImage? {
        if let key = stillKey, key.0 == frame.size, key.1 == time { return stillPicture }
        stillKey = (frame.size, time)
        stillPicture = WelcomeGlassCanvas(renderer: renderer).image(frame)
        return stillPicture
    }
}

/// The first launch's button before macOS 26: a small dark pill with a hairline edge (the mock's).
private struct WelcomeButtonStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .font(.system(size: 12.5, weight: .medium))
            .foregroundStyle(Theme.textPrimary)
            .padding(.horizontal, 16)
            .frame(height: 28)
            .background(Capsule().fill(Color(hex: 0x16171B, opacity: 0.92)))
            .overlay(Capsule().strokeBorder(Color.white.opacity(0.14), lineWidth: 1))
            .shadow(color: Color.black.opacity(0.45), radius: 9, y: 6)
            .scaleEffect(configuration.isPressed ? 0.98 : 1)
            .animation(Motion.press, value: configuration.isPressed)
            .contentShape(Capsule())
    }
}
